 pace, 90 sec then 60 sec rest","lv":"JH"},{"t":"[B] 400m + 200m + 200m at 800 pace, 90 sec then 60 sec rest","lv":"JH"},{"t":"[C] 300m + 200m at 800 pace, 90 sec rest","lv":"JH"},{"t":"Cool-down: 5–10 min Easy.","lv":"JH"}],"gfocus":{"JH Mid Distance":"BC Broken Race"},"focus":"BC Broken Race"},{"start":"2027-04-19","day":"Thu","lv":"JH","group":"Distance","items":[{"t":"Warm-up: 10–15 min Easy + drills (shorter for younger runners).","lv":"JH"},{"t":"BC Mystery Workout: draw a card or pick one. Every option is the same work.","lv":"JH"},{"t":"[A] (a) 3 × 400m · (b) 4 × 300m · (c) 6 × 200m at 1600 pace (2–3 min / 2 min / 90 sec recovery)","lv":"JH"},{"t":"[B] (a) 2–3 × 400m · (b) 3–4 × 300m · (c) 5 × 200m at 1600 pace","lv":"JH"},{"t":"[C] (a) 2 × 400m · (b) 3 × 300m · (c) 4 × 200m at 1600 pace","lv":"JH"},{"t":"Still tired from Monday? Easy run instead.","lv":"JH"},{"t":"Cool-down: 5–10 min Easy.","lv":"JH"}],"gfocus":{"JH Distance":"BC Mystery Workout"},"focus":"BC Mystery Workout"},{"start":"2027-04-19","day":"Thu","lv":"JH","group":"Mid Distance","items":[{"t":"Warm-up: 10–15 min Easy + drills (shorter for younger runners).","lv":"JH"},{"t":"BC Mystery Workout: draw a card or pick one. Every option is the same work, full recovery.","lv":"JH"},{"t":"(a) 4 × 150m relaxed fast · (b) 3 × 200m at 800 pace · (c) 6 × 100m fast, walk back","lv":"JH"},{"t":"Foundation: 3 reps of (a), 2 of (b), or 5 of (c).","lv":"JH"},{"t":"Still tired from Monday? Easy run instead.","lv":"JH"},{"t":"Cool-down: 5–10 min Easy.","lv":"JH"}],"gfocus":{"JH Mid Distance":"BC Mystery Workout"},"focus":"BC Mystery Workout"}]$plan$::jsonb;
  cur jsonb; p jsonb; dd jsonb; keep jsonb; f jsonb; lv text; g text;
  fw int; fd int; n int := 0; miss int := 0;
begin
  select value into cur from public.hub_data where key = 'workouts' for update;
  if cur is null or jsonb_typeof(cur) <> 'array' then raise exception 'No posted workouts found. Run the plan files first.'; end if;

  for p in select * from jsonb_array_elements(patches) loop
    lv := p ->> 'lv'; g := p ->> 'group';
    fw := null; fd := null;
    for i in 0 .. jsonb_array_length(cur) - 1 loop
      if cur -> i ->> 'start' = p ->> 'start' then fw := i; end if;
    end loop;
    if fw is not null then
      for j in 0 .. jsonb_array_length(coalesce(cur -> fw -> 'days', '[]'::jsonb)) - 1 loop
        if cur -> fw -> 'days' -> j ->> 'day' = p ->> 'day' then fd := j; end if;
      end loop;
    end if;
    if fd is null then
      miss := miss + 1;
      raise notice 'Skipped % % (% %): that day is not posted yet', p ->> 'start', p ->> 'day', lv, g;
      continue;
    end if;

    dd := cur -> fw -> 'days' -> fd;
    if dd -> 'groups' is null or jsonb_typeof(dd -> 'groups') <> 'object' then dd := jsonb_set(dd, '{groups}', '{}'::jsonb); end if;
    select coalesce(jsonb_agg(x), '[]'::jsonb) into keep
      from jsonb_array_elements(coalesce(dd -> 'groups' -> g, '[]'::jsonb)) x
      where coalesce(x ->> 'lv', '') <> lv;
    dd := jsonb_set(dd, array['groups', g], keep || (p -> 'items'));

    if p -> 'gfocus' <> '{}'::jsonb then
      dd := jsonb_set(dd, '{gfocus}', coalesce(nullif(dd -> 'gfocus', 'null'::jsonb), '{}'::jsonb) || (p -> 'gfocus'));
    end if;
    if p ? 'focus' then
      f := dd -> 'focus';
      if f is null or jsonb_typeof(f) = 'null' or (jsonb_typeof(f) = 'string' and f #>> '{}' = '') then
        f := '{}'::jsonb;
      elsif jsonb_typeof(f) = 'string' then
        f := jsonb_build_object('HS', f #>> '{}', 'JH', f #>> '{}');
      end if;
      dd := jsonb_set(dd, '{focus}', f || jsonb_build_object(lv, p ->> 'focus'));
      if jsonb_typeof(dd -> 'sess' -> lv) = 'object' then
        dd := jsonb_set(dd, array['sess', lv, 'title'], to_jsonb(p ->> 'focus'));
      end if;
    end if;

    cur := jsonb_set(cur, array[fw::text, 'days', fd::text], dd);
    n := n + 1;
  end loop;

  insert into public.hub_data (key, value, updated_at) values ('workouts', cur, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  raise notice 'Signature workouts posted: % of % sessions updated (% skipped).', n, jsonb_array_length(patches), miss;
end
$do$;
